import{_ as o}from"./chunks/OpenMQTTgateway_M5_Stack_Board_Display_Text.CxNzbM7o.js";import{_ as t,o as a,c as i,a6 as s}from"./chunks/framework.BJFjZBwW.js";const r="/dev/assets/OpenMQTTgateway_M5_StickC_Board_Display_Text.DWCYlKCj.png",w=JSON.parse('{"title":"Boards","description":"","frontmatter":{},"headers":[],"relativePath":"use/boards.md","filePath":"use/boards.md","lastUpdated":1724450104000}'),n={name:"use/boards.md"};function d(l,e,c,h,u,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="boards" tabindex="-1">Boards <a class="header-anchor" href="#boards" aria-label="Permalink to &quot;Boards&quot;">​</a></h1><h2 id="esp" tabindex="-1">ESP <a class="header-anchor" href="#esp" aria-label="Permalink to &quot;ESP&quot;">​</a></h2><h3 id="erasing-the-flash" tabindex="-1">Erasing the flash <a class="header-anchor" href="#erasing-the-flash" aria-label="Permalink to &quot;Erasing the flash&quot;">​</a></h3><p>So as to erase the flash memory on ESP boards you may do a long press to TRIGGER_GPIO button or connect the pin TRIGGER_GPIO to the ground during several seconds.</p><p>On M5Stack boards you may do a long press to these buttons in low power mode 0 (see below how to go to low power mode 0):</p><ul><li>Button B on M5StickC and M5StickC Plus (GPIO 37)</li><li>Button C on M5Stack (GPIO 37)</li><li>Button lateral on M5stick (GPIO 35)</li></ul><p>You can also do a long press when powering the board to reset it, this press must be done during the first 5 seconds after the start.</p><h3 id="wifi-interference-on-sensors-when-using-an-esp" tabindex="-1">Wifi interference on sensors when using an ESP <a class="header-anchor" href="#wifi-interference-on-sensors-when-using-an-esp" aria-label="Permalink to &quot;Wifi interference on sensors when using an ESP&quot;">​</a></h3><p>Certain sensors like HC-SR501 is prone to generate false signals / triggers when used on a ESP with Wifi enabled. To reduce or eliminate the effect the board must be put into Wifi B/G with lower TX power.</p><p>This can be achieved with the following macro, <code>WifiGMode</code> defined true and <code>WifiPower</code> to e.g. WIFI_POWER_11dBm (ESP32) or 11 (ESP8266).</p><p>Since the WiFi protocol is persisted in the flash of the ESP you have to run at least once with <code>WiFiGMode</code> defined <strong>false</strong> to get Band N back.</p><h3 id="low-power-mode-for-esp32" tabindex="-1">Low power mode for ESP32 <a class="header-anchor" href="#low-power-mode-for-esp32" aria-label="Permalink to &quot;Low power mode for ESP32&quot;">​</a></h3><p>OpenMQTTGateway support a low power mode for ESP32, the boards needs to have the macro <code>DEFAULT_LOW_POWER_MODE</code> defined at <code>ALWAYS_ON</code>, <code>INTERVAL</code> or <code>ACTION</code> to use it. More information about the modes is available into User_config.h.</p><p>When available this mode can be set by MQTT:</p><ul><li>Normal mode (per default)</li></ul><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;powermode&quot;:0, &quot;save&quot;:true}&#39;</code></p><ul><li>Low Power mode wake up from interval defined by DEEP_SLEEP_IN_US and pins defined by ESP32_EXT0_WAKE_PIN and/or ESP32_EXT1_WAKE_PIN</li></ul><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;powermode&quot;:1, &quot;save&quot;:true}&#39;</code></p><ul><li>Low Power mode wake up from pins defined by ESP32_EXT0_WAKE_PIN and/or ESP32_EXT1_WAKE_PIN</li></ul><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoSYS/config&quot; -m &#39;{&quot;powermode&quot;:2, &quot;save&quot;:true}&#39;</code></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A low power mode switch is automatically created by discovery with Home Assistant, you may experience a delay between the command and the state update due to the fact that the update will be received and acknowledged when the device woke up. If you are publishing the state change while the device is asleep use the retain flag. This way the device will retrieve the powermode command at wake up.</p></div><p>The default sleep time is defined by the macro <code>DEEP_SLEEP_IN_US</code> (default 60s)</p><p>We can also use an external sensor state to wake-up the ESP, this is defined by macro <code>ESP32_EXT0_WAKE_PIN/ESP32_EXT1_WAKE_PIN</code>, the level is defined by the macro <code>ESP32_EXT0_WAKE_PIN_STATE/ESP32_EXT0_WAKE_PIN_STATE</code> (default to HIGH).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you change the default low power mode to INTERVAL or ACTION and your credential are not set or not correct, the ESP32 will not connect to the broker and the only way to change the low power mode will be a new erase/upload.</p></div><h2 id="m5stickc-m5stickc-plus-or-m5stack" tabindex="-1">M5StickC, M5StickC Plus or M5Stack <a class="header-anchor" href="#m5stickc-m5stickc-plus-or-m5stack" aria-label="Permalink to &quot;M5StickC, M5StickC Plus or M5Stack&quot;">​</a></h2><h3 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h3><p>If the connection of the board to WiFi and MQTT is successful you will see the logo with text like below:</p><p><img src="'+o+'" alt="boards"></p><p>The same behaviour apply to M5StickC and M5StickC Plus</p><p><img src="'+r+'" alt="boards"></p><h3 id="setting-the-log-output" tabindex="-1">Setting the log output <a class="header-anchor" href="#setting-the-log-output" aria-label="Permalink to &quot;Setting the log output&quot;">​</a></h3><p>Per default the log of the M5 boards is going to the LCD display with Errors and Warnings only, if you want to change the output at build time you can do it in <a href="https://github.com/1technophile/OpenMQTTGateway/blob/development/main/config_M5.h" target="_blank" rel="noreferrer">config_M5.h</a>.</p><p>You can also change it by MQTT. For example if you want to set to LCD</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoM5/config -m &#39;{&quot;log-display&quot;:true}&#39;</code></p><p>you can also revert it to the serial monitor:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoM5/config -m &#39;{&quot;log-display&quot;:false}&#39;</code></p>',36)])])}const _=t(n,[["render",d]]);export{w as __pageData,_ as default};
